<div class="admin-title"><div><h1>Audit log</h1><p>Kim, ne, ne zaman, IP, eski / yeni değer. Gizli alanlar maskelenir.</p></div></div>
<form class="toolbar card card-body" method="get"><?= f_input('islem', 'İşlem', $f['islem'] ?? '') ?><?= f_select('varlik', 'Kayıt türü', $entities ?: [], $f['varlik'] ?? '', 'Tümü') ?><div class="field" style="flex:0 0 auto"><span class="label">&nbsp;</span><button class="btn">Filtrele</button></div></form>
<div class="table-wrap"><table class="table responsive"><thead><tr><th>Zaman</th><th>Kullanıcı</th><th>İşlem</th><th>Kayıt</th><th>Değişiklik</th><th>IP</th></tr></thead><tbody>
<?php foreach ($rows as $a): ?><tr><td data-label="Zaman" class="nowrap"><?= e(tr_datetime($a['created_at'])) ?></td><td data-label="Kullanıcı"><?= e($a['who'] ?: 'Sistem') ?></td><td data-label="İşlem"><span class="code"><?= e($a['action']) ?></span></td><td data-label="Kayıt"><?= e(trim($a['entity_type'] . ' #' . $a['entity_id'], ' #')) ?></td>
<td data-label="Değişiklik" class="small"><?php if ($a['old_values'] || $a['new_values']): ?><details><summary>Göster</summary><?php if ($a['old_values']): ?><div><strong>Eski:</strong> <span class="code"><?= e(mb_strimwidth($a['old_values'], 0, 1500, '…')) ?></span></div><?php endif; ?><?php if ($a['new_values']): ?><div><strong>Yeni:</strong> <span class="code"><?= e(mb_strimwidth($a['new_values'], 0, 1500, '…')) ?></span></div><?php endif; ?></details><?php endif; ?></td><td data-label="IP" class="small"><?= e($a['ip']) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="6" class="muted">Kayıt yok.</td></tr><?php endif; ?></tbody></table></div>
